--- a/op_kernel/exp_tiling.h
+++ b/op_kernel/exp_tiling.h
@@ -22,7 +22,7 @@
     const uint64_t useful = std::max<uint64_t>(1, (n + 4095) / 4096);
     t.blockNum = static_cast<uint32_t>(std::max<int64_t>(1, std::min<int64_t>(cores, useful)));
     t.blockLength = (n + t.blockNum - 1) / t.blockNum;
-    t.tileElements = 4096;
+    t.tileElements = 8192;
     t.dtype = dtype;
     t.multiplier = scale * (base > 0.0f ? std::log(base) : 1.0f);
     t.shift = shift * (base > 0.0f ? std::log(base) : 1.0f);

--- a/op_kernel/foreach_norm_tiling.h
+++ b/op_kernel/foreach_norm_tiling.h
@@ -28,8 +28,12 @@
     uint64_t n, uint32_t dtype, int64_t cores, float scalar) {
     ForeachNormTilingData t{};
     t.totalLength = n;
-    t.blockNum = static_cast<uint32_t>(std::max<int64_t>(
-        1, std::min<int64_t>(cores, static_cast<int64_t>((n + 262143) / 262144))));
+    // Keep at least 16 tiles per partial while respecting runtime cores and
+    // the finalize stage's 256-byte (64 FP32 partials) local buffers.
+    const uint64_t usefulBlocks = std::max<uint64_t>(1, n / 16384);
+    const uint64_t availableBlocks = static_cast<uint64_t>(std::max<int64_t>(1, cores));
+    t.blockNum = static_cast<uint32_t>(std::min<uint64_t>(
+        64, std::min<uint64_t>(availableBlocks, usefulBlocks)));
     t.blockLength = (n + t.blockNum - 1) / t.blockNum;
     t.tileElements = 1024;
     t.dtype = dtype;

--- a/op_kernel/foreach_norm_kernel.asc
+++ b/op_kernel/foreach_norm_kernel.asc
@@ -64,7 +64,9 @@
                 accumulator += scalar.GetValue(0);
             } else {
                 const float exponent = tiling_->scalar;
-                AscendC::Power<float>(work, work, exponent, count);
+                if (exponent != 1.0f) {
+                    AscendC::Power<float>(work, work, exponent, count);
+                }
                 AscendC::PipeBarrier<PIPE_V>();
                 AscendC::ReduceSum(scalar, work, reduce, count);
                 AscendC::PipeBarrier<PIPE_ALL>();
@@ -118,7 +120,7 @@
             AscendC::ReduceMax(result, values, reduce, tiling_->blockNum);
         } else {
             AscendC::ReduceSum(result, values, reduce, tiling_->blockNum);
-            if (tiling_->mode == FOREACH_NORM_GENERAL) {
+            if (tiling_->mode == FOREACH_NORM_GENERAL && tiling_->scalar != 1.0f) {
                 AscendC::PipeBarrier<PIPE_V>();
                 AscendC::Power<float>(result, result, 1.0f / tiling_->scalar, 1);
             }
